//! Transport-neutral protocol: commands, events, envelope, snapshot.
//!
//! Every event is enveloped with `{ v, seq, ts }` (D-038 / INV-016). The UI
//! drops events at or below its last applied `seq`. TS types are generated by
//! `ts-rs` into `ui/src/bridge/generated/`.

use ll_config::{LogLevel, RuntimeConfig, RuntimeStatus, WindowMode};
use serde::{Deserialize, Serialize};
use std::time::Instant;
use ts_rs::TS;

pub const PROTOCOL_VERSION: u32 = 1;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(
    export,
    export_to = "../../../../ui/src/bridge/generated/",
    rename_all = "snake_case"
)]
pub enum SessionState {
    Setup,
    Listening,
    Paused,
    Summary,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "snake_case")]
#[ts(
    export,
    export_to = "../../../../ui/src/bridge/generated/",
    rename_all = "snake_case"
)]
pub enum SimplifiedStatus {
    Clean,
    Flagged,
    Verbatim,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(
    export,
    export_to = "../../../../ui/src/bridge/generated/",
    rename_all = "camelCase"
)]
pub struct SnapshotSegment {
    pub id: String,
    pub text: String,
    pub simplified: Option<String>,
    pub status: SimplifiedStatus,
    pub flags: Vec<String>,
    #[ts(type = "number")]
    pub start_ms: u64,
    #[ts(type = "number")]
    pub end_ms: u64,
    pub detected_language: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(
    export,
    export_to = "../../../../ui/src/bridge/generated/",
    rename_all = "camelCase"
)]
pub struct SnapshotPartial {
    pub stream_id: String,
    pub utterance_id: String,
    pub text: String,
}

/// Late-attach state. `last_seq` gates subsequent events.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(
    export,
    export_to = "../../../../ui/src/bridge/generated/",
    rename_all = "camelCase"
)]
pub struct Snapshot {
    pub state: SessionState,
    #[ts(type = "number")]
    pub last_seq: u64,
    pub session_id: Option<String>,
    pub segments: Vec<SnapshotSegment>,
    pub partial: Option<SnapshotPartial>,
    pub reversion_active: bool,
    #[ts(type = "number")]
    pub overrun_count: u64,
    pub asr_status: String,
    pub language: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
#[ts(
    export,
    export_to = "../../../../ui/src/bridge/generated/",
    rename_all = "snake_case"
)]
pub enum CoreEvent {
    State {
        state: SessionState,
        session_id: String,
    },
    Partial {
        stream_id: String,
        utterance_id: String,
        text: String,
        confidence: Option<f32>,
    },
    Segment {
        id: String,
        text: String,
        #[ts(type = "number")]
        start_ms: u64,
        #[ts(type = "number")]
        end_ms: u64,
    },
    Simplified {
        id: String,
        text: String,
        status: SimplifiedStatus,
        flags: Vec<String>,
        #[ts(type = "number")]
        latency_ms: u64,
    },
    Reversion {
        active: bool,
        count: u32,
    },
    Download {
        repo: String,
        file: String,
        #[ts(type = "number")]
        received: u64,
        #[ts(type = "number")]
        total: u64,
        #[ts(type = "number")]
        bytes_per_sec: u64,
        #[ts(type = "number")]
        eta_ms: u64,
    },
    /// First-run model download progress (throttled per file).
    ModelProgress {
        id: String,
        file: String,
        #[ts(type = "number")]
        done_bytes: u64,
        #[ts(type = "number")]
        total_bytes: u64,
    },
    ModelReady {
        id: String,
    },
    /// `code`: DISK_FULL | HASH_MISMATCH | NETWORK | CANCELLED | IO.
    ModelError {
        id: String,
        code: String,
        reason: String,
    },
    RuntimeStatus {
        status: Box<RuntimeStatus>,
    },
    Calibration {
        backend: String,
        device: String,
        ttft_ms: f64,
        tokens_per_sec: f64,
    },
    Latency {
        stage: String,
        ms: f64,
    },
    AudioOverrun {
        #[ts(type = "number")]
        count: u64,
        #[ts(type = "number")]
        dropped_ms: u64,
        recovery: String,
    },
    Error {
        code: String,
        message: String,
        recoverable: bool,
    },
    Log {
        level: LogLevel,
        code: String,
        message: String,
    },
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(
    export,
    export_to = "../../../../ui/src/bridge/generated/",
    rename_all = "camelCase"
)]
pub struct Envelope {
    pub v: u32,
    #[ts(type = "number")]
    pub seq: u64,
    #[ts(type = "number")]
    pub ts: u64,
    pub event: CoreEvent,
}

/// Monotonic envelope factory. `ts` is milliseconds since the emitter started.
#[derive(Debug)]
pub struct EventEmitter {
    seq: u64,
    start: Instant,
    last_ts: u64,
}

impl Default for EventEmitter {
    fn default() -> Self {
        Self::new()
    }
}

impl EventEmitter {
    pub fn new() -> Self {
        Self {
            seq: 0,
            start: Instant::now(),
            last_ts: 0,
        }
    }

    pub fn last_seq(&self) -> u64 {
        self.seq
    }

    pub fn emit(&mut self, event: CoreEvent) -> Envelope {
        self.seq += 1;
        let now = self.start.elapsed().as_millis() as u64;
        // Keep ts monotonic even if the clock resolution is coarse.
        let ts = now.max(self.last_ts + 1);
        self.last_ts = ts;
        Envelope {
            v: PROTOCOL_VERSION,
            seq: self.seq,
            ts,
            event,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(
    export,
    export_to = "../../../../ui/src/bridge/generated/",
    rename_all = "camelCase"
)]
pub struct SessionStart {
    pub language: String,
    pub source: String,
    pub mode: String,
    pub detection: bool,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(tag = "type", rename_all = "snake_case")]
#[ts(
    export,
    export_to = "../../../../ui/src/bridge/generated/",
    rename_all = "snake_case"
)]
pub enum Command {
    Start { start: SessionStart },
    Stop,
    Pause,
    Resume,
    Simplify { segment_id: String },
    CancelSimplify { segment_id: String },
    SetLearningLanguage { code: String },
    ListAudioSources,
    SelectAudioSource { id: String },
    DownloadModels { manifest: String },
    CancelDownload,
    Export { format: String, path: String },
    GetSnapshot,
    GetRuntimeStatus,
    ApplyRuntimeConfig { config: RuntimeConfig },
    ProbeBackends,
    Calibrate,
    ReloadModel,
    SetWindowMode { mode: WindowMode },
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn envelope_sequence_and_timestamp_are_monotonic() {
        let mut emitter = EventEmitter::new();
        let first = emitter.emit(CoreEvent::Log {
            level: LogLevel::Info,
            code: "test".into(),
            message: "first".into(),
        });
        let second = emitter.emit(CoreEvent::Reversion {
            active: true,
            count: 2,
        });
        assert_eq!(first.v, PROTOCOL_VERSION);
        assert_eq!(first.seq, 1);
        assert_eq!(second.seq, 2);
        assert!(second.ts > first.ts);
        assert_eq!(emitter.last_seq(), 2);
    }

    #[test]
    fn event_json_uses_type_tag_and_camel_case_fields() {
        let event = CoreEvent::AudioOverrun {
            count: 3,
            dropped_ms: 120,
            recovery: "batch".into(),
        };
        let json = serde_json::to_value(&event).unwrap();
        assert_eq!(json["type"], "audio_overrun");
        assert_eq!(json["dropped_ms"], 120);
        let snapshot = Snapshot {
            state: SessionState::Listening,
            last_seq: 7,
            session_id: Some("s1".into()),
            segments: vec![],
            partial: None,
            reversion_active: false,
            overrun_count: 0,
            asr_status: "simplify_only".into(),
            language: "de-DE".into(),
        };
        let json = serde_json::to_string(&snapshot).unwrap();
        assert!(json.contains("\"lastSeq\":7"));
        assert!(json.contains("\"asrStatus\":\"simplify_only\""));
    }

    #[test]
    fn command_round_trip() {
        let command = Command::Simplify {
            segment_id: "seg-1".into(),
        };
        let json = serde_json::to_string(&command).unwrap();
        assert!(json.contains("\"type\":\"simplify\""));
        let decoded: Command = serde_json::from_str(&json).unwrap();
        assert_eq!(decoded, command);
    }
}
